import { useEffect, useMemo, useState, type ReactNode } from "react";
import { api } from "./api";
import { IssueFocusBanner, type Persona as IssuePersona } from "./PersonaIssuesNotifications";

type Project = { id: string; project_number: string; project_name: string };
type Client = { id: string; reference: string; name: string; status: string };
type Persona = "SYSTEM_ADMIN" | "COMMERCIAL_APPROVER" | "RESPONSIBLE_ENGINEER";
type ActionKey = "CLIENT_LIST" | "PROPOSAL_FORM" | "CONTRACT_FORM";
type SourceKey = "TENDER_EMAIL" | "TENDER_DOCUMENT" | "TENDER_IMAGE" | "CLIENT_INFORMATION";

const actions: Array<{ key: ActionKey; label: string; helper: string; semantic: string }> = [
  { key: "CLIENT_LIST", label: "Client List", helper: "Client master source", semantic: "CLIENT_SOURCE" },
  { key: "PROPOSAL_FORM", label: "Proposal Form", helper: "Attach to an eligible Proposal", semantic: "PROPOSAL_SOURCE" },
  { key: "CONTRACT_FORM", label: "Contract Form", helper: "Attach to an eligible Contract", semantic: "CONTRACT_SOURCE" },
];
const sources: Array<{ key: SourceKey; label: string; helper: string }> = [
  { key: "TENDER_EMAIL", label: "Tender Email", helper: "Email or saved message/PDF" },
  { key: "TENDER_DOCUMENT", label: "Tender Document", helper: "RFQ, RFP, tender or client brief" },
  { key: "TENDER_IMAGE", label: "Tender Photo / Image", helper: "Manual image or screenshot" },
  { key: "CLIENT_INFORMATION", label: "Client Information", helper: "Client source or supporting document" },
];
const kpiOrder = ["OPEN_PROPOSALS", "OPEN_CONTRACTS", "PROPOSAL_HANDOVER", "CONTRACT_HANDOVER", "PROPOSALS_IN_PROCESS", "CONTRACTS_IN_PROCESS"];
const roleLabels: Record<Persona, string> = { SYSTEM_ADMIN: "Owner", COMMERCIAL_APPROVER: "Business Development", RESPONSIBLE_ENGINEER: "Engineering" };
const issuePersona = (persona: Persona): IssuePersona => persona === "COMMERCIAL_APPROVER" ? "BUSINESS_DEVELOPMENT" : persona === "RESPONSIBLE_ENGINEER" ? "ENGINEERING" : "OWNER";

export function ProposalsContractsPage({ projects, persona, openRecord }: { projects: Project[]; persona: Persona; openRecord: (projectId: string) => void }) {
  const [routePath, setRoutePath] = useState(() => window.location.pathname);
  useEffect(() => {
    const syncRoute = () => setRoutePath(window.location.pathname);
    window.addEventListener("popstate", syncRoute);
    return () => window.removeEventListener("popstate", syncRoute);
  }, []);
  const routeNew = routePath === "/proposals/new";
  const routeProposalId = routePath.match(/^\/proposals\/([^/]+)$/)?.[1] || null;
  const routePreparationId = routePath.match(/^\/proposals\/([^/]+)\/preparation$/)?.[1] || null;
  const routeContractId = routePath.match(/^\/contracts\/([^/]+)$/)?.[1] || null;
  const [data, setData] = useState<any>(null);
  const [filter, setFilter] = useState("ALL");
  const [tab, setTab] = useState<"proposals" | "contracts">("proposals");
  const [selectedProposal, setSelectedProposal] = useState<string | null>(null);
  const [modal, setModal] = useState<ActionKey | SourceKey | "NEW_PROPOSAL" | null>(routeNew ? "NEW_PROPOSAL" : null);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigateRoute = (route: string) => { window.history.pushState({}, "", route); window.dispatchEvent(new PopStateEvent("popstate")); };
  const load = async () => { setLoading(true); setError(""); try { setData(await api<any>(`/api/proposals-main?persona=${persona}`)); } catch (value) { setError(value instanceof Error ? value.message : "Proposal and Contract register unavailable."); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [persona]);
  const allowed = (data?.persona?.allowed_actions || []) as ActionKey[];
  const sourceActions = (data?.persona?.source_actions || []) as SourceKey[];
  const visibleActions = actions.filter((item) => allowed.includes(item.key));
  const visibleSources = sources.filter((item) => sourceActions.includes(item.key));
  const rows = (data?.rows || []) as any[];
  const contractRows = (data?.contract_rows || []) as any[];
  const filteredRows = useMemo(() => rows.filter((row) => {
    const states = data?.filter_predicates?.proposal?.[filter];
    if (states === undefined || states === null) return true;
    return states.includes(row.proposal_status);
  }), [rows, filter, data]);
  const filteredContractRows = useMemo(() => contractRows.filter((row) => {
    const states = data?.filter_predicates?.contract?.[filter];
    if (states === undefined || states === null) return true;
    return states.includes(row.status);
  }), [contractRows, filter, data]);
  const transition = async (url: string, success: string) => { setMessage(""); try { const result = await api<any>(url, { method: "POST" }); setMessage(success); await load(); if (result.next_route) navigateRoute(result.next_route); } catch (value) { setMessage(value instanceof Error ? value.message : "The human transition was blocked."); } };

  const backToRegister = () => {
    window.history.pushState({}, "", "/proposals-contracts"); window.dispatchEvent(new PopStateEvent("popstate"));
  };

  if (routeNew && (persona === "RESPONSIBLE_ENGINEER" || (data && !allowed.includes("NEW_PROPOSAL" as ActionKey)))) return <div className="workflow-page proposals-main route-detail-page route-new-proposal access-restricted-page"><section className="panel access-restricted-card" role="status"><span className="eyebrow">NEW PROPOSAL</span><h2>New Proposal intake is handled by Business Development.</h2><p>Engineering owns Proposal Preparation and technical handoff after a Proposal exists.</p><button className="button-primary" onClick={backToRegister}>Back to Proposals &amp; Contracts</button></section></div>;
  if (routeNew && !data) return <div className="workflow-page proposals-main route-detail-page route-new-proposal"><section className="panel"><b>Loading New Proposal intake…</b></section></div>;
  if (routeNew) return <div className="workflow-page proposals-main route-detail-page route-new-proposal"><div className="page-intro proposals-main-intro"><div><span className="eyebrow">AMEC · PROPOSAL INTAKE</span><h2>New Proposal</h2><p>Start a Proposal from tender and client information. If a canonical AMEC Project Reference has not been assigned yet, ProposalOps keeps the intake under a controlled provisional Proposal Reference until the Project Reference is available.</p></div><span className="tag">{roleLabels[persona]}</span></div><ProposalIntakePage initialSource={null} persona={persona} projects={projects} clients={data.clients || []} onClose={backToRegister} onComplete={(result) => { if (result.proposalId) navigateRoute(`/proposals/${result.proposalId}`); }} /></div>;
  if (routePreparationId) return <div className="workflow-page proposals-main route-detail-page"><IssueFocusBanner persona={issuePersona(persona)} /><ProposalPreparationInline proposalId={routePreparationId} persona={persona} onClose={backToRegister} onMessage={setMessage} /></div>;
  if (routeProposalId) return <div className="workflow-page proposals-main route-detail-page"><IssueFocusBanner persona={issuePersona(persona)} /><ProposalDetailInline proposalId={routeProposalId} persona={persona} projects={projects} onBack={backToRegister} onTransition={transition} navigateRoute={navigateRoute} /></div>;
  if (routeContractId) return <div className="workflow-page proposals-main route-detail-page"><IssueFocusBanner persona={issuePersona(persona)} /><ContractDetailInline contractId={routeContractId} persona={persona} onBack={backToRegister} onPermit={(id) => transition(`/api/proposals-main/contracts/${id}/permit`, "Downstream Permit workspace linked to this Contract.")} navigateRoute={navigateRoute} /></div>;

  if (loading && !data) return <div className="workflow-page proposals-main"><section className="panel"><b>Loading Proposals &amp; Contracts…</b></section></div>;
  if (error && !data) return <div className="workflow-page proposals-main"><section className="panel error-state" role="alert"><h2>Proposals &amp; Contracts unavailable</h2><p>{error}</p><button className="button-primary" onClick={() => void load()}>Retry</button></section></div>;

  return <div className="workflow-page proposals-main">
    <div className="page-intro proposals-main-intro"><div><span className="eyebrow">AMEC · PROPOSAL • CONTRACT • PERMIT</span><h2>Proposals &amp; Contracts</h2><p>One governed commercial register from source intake to Proposal, Contract, and downstream Permit handoff.</p></div><span className="tag">{roleLabels[persona]}</span></div>
    {message && <div className="inline-message" role="status">{message}</div>}
    <div className="proposal-action-row" aria-label="Manual source actions">
      {visibleSources.map((item) => <button key={item.key} className="proposal-orange-action" onClick={() => { setMessage(""); setModal(item.key); }}><span>{item.label}</span><small>{item.helper}</small></button>)}
      {visibleActions.map((item) => <button key={item.key} className="proposal-orange-action" onClick={() => { setMessage(""); setModal(item.key); }}><span>{item.label}</span><small>{item.helper}</small></button>)}
    </div>
    <div className="proposal-kpi-grid">{kpiOrder.map((key) => { const kpi = data.kpis[key]; return <button key={key} className={`proposal-kpi ${filter === key ? "selected" : ""}`} onClick={() => { const nextTab = key.includes("CONTRACT") ? "contracts" : "proposals"; setTab(nextTab); setFilter(filter === key ? "ALL" : key); }}><span>{kpi.label}</span><strong>{kpi.count}</strong><small>System-derived · click to filter</small></button>; })}</div>
    <section className="panel proposals-table-panel">
      <div className="proposals-toolbar"><div className="register-tabs"><button className={tab === "proposals" ? "active" : ""} onClick={() => { setTab("proposals"); if (data.filter_predicates.proposal[filter] === undefined) setFilter("ALL"); }}>Proposals</button><button className={tab === "contracts" ? "active" : ""} onClick={() => { setTab("contracts"); if (data.filter_predicates.contract[filter] === undefined) setFilter("ALL"); }}>Contracts</button></div><div className="filter-row">{(data.filters || []).filter((item: any) => item.key === "ALL" || data.filter_predicates[tab === "proposals" ? "proposal" : "contract"][item.key] !== undefined).map((item: any) => <button key={item.key} className={`filter ${filter === item.key ? "active" : ""}`} onClick={() => setFilter(item.key)}>{item.label}</button>)}</div>{persona !== "RESPONSIBLE_ENGINEER" && allowed.includes("NEW_PROPOSAL" as ActionKey) && <button className="button-primary proposal-new-button" onClick={() => navigateRoute("/proposals/new")}>＋ New Proposal</button>}</div>
      {tab === "proposals" ? <div className="table-panel"><table><thead><tr><th>Proposal Description</th><th>Project Ref.</th><th>Stage / Status</th>{data.persona.amount_visible && <th>Amount</th>}<th>Last Activity</th><th>Actions</th></tr></thead><tbody>{filteredRows.map((row) => <ProposalRow key={row.id} row={row} showAmount={data.persona.amount_visible} onOpen={() => navigateRoute(`/proposals/${row.id}`)} onProceed={() => transition(`/api/proposals-main/proposals/${row.id}/proceed`, "Proposal proceeded to Engineering Proposal Preparation.")} onContract={() => transition(`/api/proposals-main/proposals/${row.id}/contract`, "Contract created from the selected Proposal.")} onViewContract={() => navigateRoute(`/contracts/${row.related_contract_id}`)} />)}{!filteredRows.length && <EmptyRow colSpan={data.persona.amount_visible ? 6 : 5} />}</tbody></table></div> : <div className="table-panel"><table><thead><tr><th>Contract</th><th>Contract Ref.</th><th>Related Proposal</th><th>Amount</th><th>Last Activity</th><th>End Date</th><th>Actions</th></tr></thead><tbody>{filteredContractRows.map((row) => <tr key={row.id}><td><button className="text-button linkish" onClick={() => navigateRoute(`/contracts/${row.id}`)}>{row.id}</button><small className="proposal-row-sub">{row.status.replaceAll("_", " ")}</small></td><td>{row.contract_reference || "—"}</td><td>{row.related_proposal_id ? <button className="text-button" onClick={() => navigateRoute(`/proposals/${row.related_proposal_id}`)}>{row.related_proposal}</button> : "—"}</td><td>{row.amount || "—"}</td><td>{new Date(row.last_activity).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</td><td>{row.end_date || "—"}</td><td><button className="text-button" onClick={() => navigateRoute(`/contracts/${row.id}`)}>Open</button><button className="proposal-orange-link" disabled={!row.permit_eligible} title={row.permit_action?.disabled_reason || ""} onClick={() => row.permit_id ? navigateRoute(`/proposals-contracts/${row.project_id}/project-and-sources`) : transition(`/api/proposals-main/contracts/${row.id}/permit`, "Downstream Permit workspace linked to this Contract.")}>{row.permit_id ? "Open Permit" : "Permit"}</button></td></tr>)}{!filteredContractRows.length && <EmptyRow colSpan={7} />}</tbody></table></div>}
    </section>
    <div className="proposal-sor-note"><span className="proposal-blue-dot"/><span>Blue shows system-derived state. Orange marks a human-controlled source or lifecycle transition. Original evidence is retained with provenance and read-back verification.</span></div>
    {selectedProposal && <ProposalPreparationInline proposalId={selectedProposal} persona={persona} onClose={() => setSelectedProposal(null)} onMessage={setMessage} />}
    {modal && (modal === "NEW_PROPOSAL" || sources.some((item) => item.key === modal)) ? <ProposalIntakeModal initialSource={modal === "NEW_PROPOSAL" ? null : modal as SourceKey} persona={persona} projects={projects} clients={data.clients || []} onClose={() => setModal(null)} onComplete={(result) => { setMessage(result.message); if (result.proposalId) void load(); }} /> : modal ? <ManualUploadModal action={actions.find((item) => item.key === modal)!} projects={projects} proposals={data.eligible_proposals || rows} contracts={data.eligible_contracts || contractRows} persona={persona} onClose={() => setModal(null)} onComplete={(result) => { setModal(null); setMessage(`${result.source_filename || "Source"} saved · read-back verified.`); void load(); }} /> : null}
  </div>;
}

function ProposalDetailInline({ proposalId, persona, projects, onBack, onTransition, navigateRoute }: { proposalId: string; persona: Persona; projects: Project[]; onBack: () => void; onTransition: (url: string, success: string) => void; navigateRoute: (route: string) => void }) {
  const [detail, setDetail] = useState<any>(null); const [targetProject, setTargetProject] = useState(""); const [error, setError] = useState("");
  useEffect(() => { api<any>(`/api/proposals-main/proposals/${proposalId}`).then(setDetail).catch((e) => setError(e instanceof Error ? e.message : "Proposal unavailable.")); }, [proposalId]);
  if (error) return <section className="panel proposal-detail-panel"><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button><h2>{error.includes("[404") ? "Proposal not found" : "Proposal detail unavailable"}</h2><p>{error}</p><button className="button-secondary" onClick={() => { setError(""); setDetail(null); api<any>(`/api/proposals-main/proposals/${proposalId}`).then(setDetail).catch((e) => setError(e instanceof Error ? e.message : "Proposal unavailable.")); }}>Retry</button></section>;
  if (!detail) return <section className="panel proposal-detail-panel"><b>Loading Proposal detail…</b></section>;
  const proposal = detail.proposal; const promote = () => targetProject && onTransition(`/api/proposals-main/proposals/${proposalId}/promote/${targetProject}`, "Provisional sources reconciled into the canonical Project record.");
  if (detail) return <ProposalDetailSurface proposal={proposal} detail={detail} persona={persona} projects={projects} targetProject={targetProject} setTargetProject={setTargetProject} promote={promote} onBack={onBack} onTransition={onTransition} proposalId={proposalId} navigateRoute={navigateRoute} />;
  return <section className="panel proposal-detail-panel"><div className="panel-head"><div><span className="eyebrow">PROPOSAL DETAIL · {roleLabels[persona]}</span><h2>{proposal.proposal_description}</h2><p>{proposal.project_reference} · {proposal.reference_state} · {proposal.current_stage}</p></div><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button></div><div className="detail-status-strip"><span>Status <b>{proposal.proposal_status}</b></span><span>Next action <b>{proposal.next_action?.label || "Open"}</b></span><span>Client <b>{detail.readiness.client_context ? "Linked" : "Needs information"}</b></span><span>Sources <b>{proposal.source_count}</b></span></div><div className="preparation-grid"><div><h3>Proposal fields</h3>{Object.entries(detail.fields || {}).map(([key, value]) => <div className="detail-field" key={key}><small>{key.replaceAll("_", " ")}</small><b>{String(value || "—")}</b></div>)}<h3>Related Contract(s)</h3>{detail.contracts?.length ? detail.contracts.map((item: any) => <button className="detail-field detail-link" key={item.id} onClick={() => navigateRoute(`/contracts/${item.id}`)}><b>{item.reference}</b><span>{item.status}</span></button>) : <p>No Contract linked yet.</p>}</div><div><h3>Source evidence</h3>{detail.sources.map((source: any) => <div className="preparation-source" key={source.id}><span>✓</span><div><b>{source.artifact_class.replaceAll("_", " ")}</b><small>{source.filename} · v{source.version} · {source.verification_status} · {source.current ? "CURRENT" : "SUPERSEDED"}</small><small>{source.sor_binding} · {source.content_hash.slice(0, 12)}…</small></div></div>)}<h3>Issues &amp; history</h3>{detail.issues?.length ? detail.issues.map((issue: any) => <div className="detail-field" key={issue.id}>{issue.title}</div>) : <p>No linked commercial issue.</p>}<p>{detail.tasks.length} governed handoff record(s) retained.</p>{detail.tasks.map((task: any) => <div className="detail-field" key={task.id}><b>{task.title}</b><span>{task.owner_role} · {task.status}</span></div>)}</div></div>{proposal.reference_state === "PROVISIONAL" && <div className="promotion-strip"><b>Project folder link</b><span>Reconcile these retained sources once the canonical Project Reference exists.</span><select value={targetProject} onChange={(e) => setTargetProject(e.target.value)}><option value="">Select canonical Project…</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.project_number} · {project.project_name}</option>)}</select><button className="button-primary" onClick={promote} disabled={!targetProject}>Promote and verify</button></div>}<div className="detail-actions">{proposal.next_action?.code === "PROCEED" && proposal.next_action.eligible && <button className="button-primary" onClick={() => onTransition(`/api/proposals-main/proposals/${proposalId}/proceed`, "Proposal proceeded to Engineering Proposal Preparation.")}>Proceed</button>}{proposal.next_action?.code === "CREATE_CONTRACT" && proposal.next_action.eligible && <button className="proposal-orange-link" onClick={() => onTransition(`/api/proposals-main/proposals/${proposalId}/contract`, "Contract created from the selected Proposal.")}>Contract</button>}{proposal.next_action?.code === "VIEW_CONTRACT" && proposal.related_contract_id && <button className="proposal-orange-link" onClick={() => navigateRoute(`/contracts/${proposal.related_contract_id}`)}>View Contract</button>}</div></section>;
}

function ProposalDetailSurface({ proposal, detail, persona, projects, targetProject, setTargetProject, promote, onBack, onTransition, proposalId, navigateRoute }: { proposal: any; detail: any; persona: Persona; projects: Project[]; targetProject: string; setTargetProject: (value: string) => void; promote: () => void; onBack: () => void; onTransition: (url: string, success: string) => void; proposalId: string; navigateRoute: (route: string) => void }) {
  const canTransition = persona !== "RESPONSIBLE_ENGINEER";
  const label = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
  return <section className="panel proposal-detail-panel"><div className="panel-head"><div><span className="eyebrow">PROPOSAL DETAIL · {roleLabels[persona]}</span><h2>{proposal.proposal_description}</h2><p>{proposal.project_reference} · {label(proposal.reference_state)} · {proposal.current_stage}</p></div><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button></div><div className="detail-status-grid"><div><small>Status</small><b>{label(proposal.proposal_status)}</b></div><div><small>Next action</small><b>{proposal.next_action?.label || "Review record"}</b></div><div><small>Client</small><b>{detail.readiness.client_context ? "Linked" : "Information needed"}</b></div><div><small>Current sources</small><b>{proposal.source_count}</b></div></div><div className="preparation-grid"><div><h3>Proposal fields</h3>{Object.entries(detail.fields || {}).map(([key, value]) => <div className="detail-field" key={key}><small>{label(key)}</small><b>{String(value || "Not recorded")}</b></div>)}<h3>Related Contract(s)</h3>{detail.contracts?.length ? detail.contracts.map((item: any) => <button className="detail-field detail-link" key={item.id} onClick={() => navigateRoute(`/contracts/${item.id}`)}><b>{item.reference}</b><span>{label(item.status)}</span></button>) : <p>No Contract is linked to this Proposal.</p>}</div><div><h3>Source evidence</h3>{detail.sources.map((source: any) => <div className="preparation-source" key={source.id}><span>✓</span><div><b>{label(source.artifact_class || "Source")}</b><small>{source.filename} · {source.verification_status === "READ_BACK_VERIFIED" ? "Verified" : label(source.verification_status || "Recorded")} · Version {source.version}</small></div></div>)}<h3>Linked Issues</h3>{detail.issues?.length ? detail.issues.map((issue: any) => <div className="detail-field" key={issue.id}><b>{issue.title}</b><span>{label(issue.status)} · {issue.blocking ? "Blocking" : "Advisory"}</span></div>) : <p>No linked Issues are currently recorded.</p>}<h3>Handoff history</h3><p>{detail.tasks.length} governed handoff record(s) retained.</p>{detail.tasks.map((task: any) => <div className="detail-field" key={task.id}><b>{task.title}</b><span>{label(task.owner_role)} · {label(task.status)}</span></div>)}</div></div>{proposal.reference_state === "PROVISIONAL" && <div className="promotion-strip"><b>Canonical Project context</b><span>Reconcile retained sources once the canonical Project Reference exists.</span><select value={targetProject} onChange={(e) => setTargetProject(e.target.value)}><option value="">Select canonical Project…</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.project_number} · {project.project_name}</option>)}</select><button className="button-primary" onClick={promote} disabled={!targetProject || !canTransition}>Promote and verify</button></div>}<div className="detail-actions">{canTransition && proposal.next_action?.code === "PROCEED" && proposal.next_action.eligible && <button className="button-primary" onClick={() => onTransition(`/api/proposals-main/proposals/${proposalId}/proceed`, "Proposal proceeded to Engineering Proposal Preparation.")}>Proceed to Preparation</button>}{canTransition && proposal.next_action?.code === "CREATE_CONTRACT" && proposal.next_action.eligible && <button className="proposal-orange-link" onClick={() => onTransition(`/api/proposals-main/proposals/${proposalId}/contract`, "Contract created from the selected Proposal.")}>Create Contract</button>}{proposal.next_action?.code === "VIEW_CONTRACT" && proposal.related_contract_id && <button className="proposal-orange-link" onClick={() => navigateRoute(`/contracts/${proposal.related_contract_id}`)}>View Contract</button>}</div></section>;
}

function ContractDetailInline({ contractId, persona, onBack, onPermit, navigateRoute }: { contractId: string; persona: Persona; onBack: () => void; onPermit: (id: string) => void; navigateRoute: (route: string) => void }) {
  const [detail, setDetail] = useState<any>(null); const [error, setError] = useState("");
  useEffect(() => { api<any>(`/api/proposals-main/contracts/${contractId}`).then(setDetail).catch((e) => setError(e instanceof Error ? e.message : "Contract unavailable.")); }, [contractId]);
  if (error) return <section className="panel contract-detail-panel"><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button><h2>{error.includes("[404") ? "Contract not found" : "Contract detail unavailable"}</h2><p>{error}</p><button className="button-secondary" onClick={() => { setError(""); setDetail(null); api<any>(`/api/proposals-main/contracts/${contractId}`).then(setDetail).catch((e) => setError(e instanceof Error ? e.message : "Contract unavailable.")); }}>Retry</button></section>;
  if (!detail) return <section className="panel contract-detail-panel"><b>Loading Contract detail…</b></section>;
  const contract = detail.contract;
  if (detail) return <ContractDetailSurface contract={contract} detail={detail} persona={persona} contractId={contractId} onBack={onBack} onPermit={onPermit} navigateRoute={navigateRoute} />;
  return <section className="panel contract-detail-panel"><div className="panel-head"><div><span className="eyebrow">CONTRACT DETAIL · COMMERCIAL WORKFLOW</span><h2>{contract.reference}</h2><p>{contract.status} · {detail.project?.reference || "Project reference pending"}</p></div><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button></div><div className="detail-status-strip"><span>Related Proposal <button className="text-button" onClick={() => detail.proposal?.id && navigateRoute(`/proposals/${detail.proposal.id}`)}>{detail.proposal?.title || "—"}</button></span><span>Amount <b>{contract.amount || "—"}</b></span><span>End Date <b>{contract.end_date || "—"}</b></span><span>Next Action <b>{detail.next_action?.label || "—"}</b></span></div><div className="preparation-grid"><div><h3>Contract Form / revisions</h3>{detail.revisions.length ? detail.revisions.map((revision: any) => <div className="detail-field" key={revision.id}><b>Revision {revision.revision_number}</b><span>{revision.status}</span></div>) : <p>Contract Form revision pending.</p>}<h3>Project</h3><div className="detail-field"><b>{detail.project?.reference || "—"}</b><span>{detail.project?.name || "Canonical project context pending"}</span></div></div><div><h3>Commercial state</h3><div className="detail-field"><small>Related Proposal</small><button className="text-button" onClick={() => detail.proposal?.id && navigateRoute(`/proposals/${detail.proposal.id}`)}>{detail.proposal?.reference || "—"}</button></div><div className="detail-field"><small>Permit handoff</small><b>{detail.permits.length ? `${detail.permits.length} linked Permit(s)` : "Eligible when downstream Permit exists"}</b></div><h3>Source provenance</h3>{detail.sources.map((source: any) => <div className="preparation-source" key={source.id}><span>✓</span><div><b>{source.artifact_class.replaceAll("_", " ")}</b><small>{source.path} · {source.verification_status}</small></div></div>)}<h3>Issues &amp; history</h3><p>{detail.issues?.length || 0} linked issue(s) · {detail.history?.length || 0} audit event(s).</p></div></div><div className="detail-actions">{detail.permits.length ? <button className="proposal-orange-link" onClick={() => detail.project?.id && navigateRoute(`/proposals-contracts/${detail.project.id}/project-and-sources`)}>Open Permit</button> : <button className="proposal-orange-link" disabled={!detail.next_action?.eligible} title={detail.next_action?.disabled_reason || ""} onClick={() => onPermit(contractId)}>Permit</button>}</div></section>;
}

function ContractDetailSurface({ contract, detail, persona, contractId, onBack, onPermit, navigateRoute }: { contract: any; detail: any; persona: Persona; contractId: string; onBack: () => void; onPermit: (id: string) => void; navigateRoute: (route: string) => void }) {
  const label = (value: string) => String(value || "Not recorded").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
  const canInitiatePermit = persona !== "RESPONSIBLE_ENGINEER";
  return <section className="panel contract-detail-panel"><div className="panel-head"><div><span className="eyebrow">CONTRACT DETAIL · {roleLabels[persona]}</span><h2>{contract.reference}</h2><p>{label(contract.status)} · {detail.project?.reference || "Project reference pending"}</p></div><button className="text-button" onClick={onBack}>← Proposals &amp; Contracts</button></div><div className="detail-status-grid"><div><small>Related Proposal</small>{detail.proposal?.id ? <button className="text-button" onClick={() => navigateRoute(`/proposals/${detail.proposal.id}`)}>{detail.proposal.reference}</button> : <b>Not linked</b>}</div><div><small>Amount</small><b>{contract.amount || "Not recorded"}</b></div><div><small>End date</small><b>{contract.end_date ? new Date(contract.end_date).toLocaleDateString() : "Not recorded"}</b></div><div><small>Next action</small><b>{detail.next_action?.label || "Review record"}</b></div></div><div className="preparation-grid"><div><h3>Contract revisions</h3>{detail.revisions.length ? detail.revisions.map((revision: any) => <div className="detail-field" key={revision.id}><b>Revision {revision.revision_number}</b><span>{label(revision.status)}</span></div>) : <p>No Contract revision is recorded.</p>}<h3>Project context</h3><div className="detail-field"><b>{detail.project?.reference || "Not recorded"}</b><span>{detail.project?.name || "Project context pending"}</span></div></div><div><h3>Commercial handoff</h3><div className="detail-field"><small>Linked Proposal</small><b>{detail.proposal?.reference || "Not linked"}</b><span>{detail.proposal?.status ? label(detail.proposal.status) : "Not recorded"}</span></div><div className="detail-field"><small>Permit handoff</small><b>{detail.permits.length ? `${detail.permits.length} linked Permit record(s)` : "No downstream Permit linked"}</b><span>{detail.permits.length ? "Lifecycle handoff recorded" : "Permit initiation remains pending"}</span></div><h3>Source provenance</h3>{detail.sources.length ? detail.sources.map((source: any) => <div className="preparation-source" key={source.id}><span>✓</span><div><b>{label(source.artifact_class || "Source")}</b><small>{source.verification_status === "READ_BACK_VERIFIED" ? "Verified" : label(source.verification_status || "Recorded")}</small></div></div>) : <p>No Contract source is recorded.</p>}<h3>Linked Issues &amp; history</h3>{detail.issues?.length ? detail.issues.map((issue: any) => <div className="detail-field" key={issue.id}><b>{issue.title}</b><span>{label(issue.status)} · {issue.blocking ? "Blocking" : "Advisory"}</span></div>) : <p>No linked Issues are currently recorded.</p>}<p>{detail.history?.length || 0} audit event(s) retained.</p></div></div><div className="detail-actions">{detail.permits.length ? <button className="proposal-orange-link" onClick={() => detail.project?.id && navigateRoute(`/proposals-contracts/${detail.project.id}/project-and-sources`)}>Open Permit</button> : canInitiatePermit && <button className="proposal-orange-link" disabled={!detail.next_action?.eligible} title={detail.next_action?.disabled_reason || ""} onClick={() => onPermit(contractId)}>Initiate Permit</button>}</div></section>;
}

function ProposalPreparationInline({ proposalId, persona, onClose, onMessage }: { proposalId: string; persona: Persona; onClose: () => void; onMessage: (value: string) => void }) {
  const [detail, setDetail] = useState<any>(null); const [busy, setBusy] = useState(false);
  useEffect(() => { api<any>(`/api/proposals-main/proposals/${proposalId}`).then(setDetail).catch((error) => onMessage(error.message)); }, [proposalId]);
  const ready = async () => { setBusy(true); try { await api(`/api/proposals-main/proposals/${proposalId}/engineering-ready`, { method: "POST", headers: { "X-Dev-Role": persona } }); onMessage("Engineering returned the same Proposal to Business Development for commercial review."); const next = await api<any>(`/api/proposals-main/proposals/${proposalId}`); setDetail(next); } catch (error) { onMessage(error instanceof Error ? error.message : "Engineering handoff is blocked."); } finally { setBusy(false); } };
  if (!detail) return <section className="panel proposal-preparation-panel"><b>Loading Proposal Preparation…</b></section>;
  const fields = [["Scope of work", detail.fields.sow], ["Process of Work", detail.fields.process_of_work], ["Technical exclusions", detail.fields.technical_exclusions], ["Delivery period", detail.fields.period]];
  const engineering = persona === "RESPONSIBLE_ENGINEER" || persona === "SYSTEM_ADMIN";
  return <section className="panel proposal-preparation-panel"><div className="panel-head"><div><span className="eyebrow">PROPOSAL PREPARATION · {roleLabels[persona]}</span><h3>Proposal Preparation</h3><p>{detail.proposal.proposal_description} · {detail.proposal.project_reference}</p></div><button className="text-button" onClick={onClose}>Close</button></div><div className="preparation-grid"><div><h3>Inputs &amp; Sources</h3>{detail.sources.map((source: any) => <div className="preparation-source" key={source.id}><span>✓</span><div><b>{(source.semantic_class || source.artifact_class || "Source").replaceAll("_", " ")}</b><small>{source.filename} · {source.verification_status === "READ_BACK_VERIFIED" ? "Verified" : source.verification_status}</small></div></div>)}</div><div><h3>Technical preparation</h3>{fields.map(([label, value]) => engineering && label !== "Delivery period" ? <label className="preparation-field" key={String(label)}>{label}<input defaultValue={String(value || "Needs review")} /></label> : <div className="detail-field" key={String(label)}><small>{label}</small><b>{String(value || "Not recorded")}</b></div>)}</div></div><div className="preparation-handoff"><span>{engineering ? "Engineering owns the technical scope and can return this Proposal to Business Development when the preparation decision is complete." : "Context only: Engineering owns technical preparation. Business Development may review the persisted scope and handoff state."}</span>{engineering && <button className="button-primary" onClick={ready} disabled={busy || detail.proposal.proposal_status !== "PROPOSAL_PREPARATION"}>{busy ? "Returning…" : "Ready for BD"}</button>}</div></section>;
}
function ProposalRow({ row, showAmount, onOpen, onProceed, onContract, onViewContract }: { row: any; showAmount: boolean; onOpen: () => void; onProceed: () => void; onContract: () => void; onViewContract: () => void }) { return <tr><td><button className="text-button linkish" onClick={onOpen}>{row.proposal_description}</button><small className="proposal-row-sub">{row.reference_state} · {row.source_count} source(s)</small></td><td><b>{row.project_reference}</b><small className="proposal-row-sub">{row.project_name}</small></td><td><span className="status status-under-review">{row.current_stage}</span></td>{showAmount && <td>{row.amount || "—"}</td>}<td>{new Date(row.last_activity).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</td><td><button className="text-button" onClick={onOpen}>Open</button>{row.next_action?.code === "PROCEED" && row.next_action.eligible && <button className="proposal-orange-link" onClick={onProceed}>Proceed</button>}{row.next_action?.code === "CREATE_CONTRACT" && row.next_action.eligible && <button className="proposal-orange-link" onClick={onContract}>Contract</button>}{row.next_action?.code === "VIEW_CONTRACT" && <button className="proposal-orange-link" onClick={onViewContract}>View Contract</button>}</td></tr>; }
function EmptyRow({ colSpan }: { colSpan: number }) { return <tr><td colSpan={colSpan}><div className="empty-state"><b>No records match this view.</b><p>Blue state cards and register rows are computed from the same ProposalOps records.</p></div></td></tr>; }

function ProposalIntakeModal(props: { initialSource: SourceKey | null; persona: Persona; projects: Project[]; clients: Client[]; onClose: () => void; onComplete: (result: { message: string; proposalId?: string }) => void }) {
  return <Modal title={props.initialSource ? `New Proposal from ${sources.find((item) => item.key === props.initialSource)?.label}` : "New Proposal"} onClose={props.onClose}><ProposalIntakeForm {...props} /></Modal>;
}

function ProposalIntakePage(props: { initialSource: SourceKey | null; persona: Persona; projects: Project[]; clients: Client[]; onClose: () => void; onComplete: (result: { message: string; proposalId?: string }) => void }) {
  return <section className="panel proposal-intake-page-panel"><ProposalIntakeForm {...props} fullPage /></section>;
}

function ProposalIntakeForm({ initialSource, persona, projects, clients, onClose, onComplete, fullPage = false }: { initialSource: SourceKey | null; persona: Persona; projects: Project[]; clients: Client[]; onClose: () => void; onComplete: (result: { message: string; proposalId?: string }) => void; fullPage?: boolean }) {
  const [description, setDescription] = useState("");
  const [fields, setFields] = useState({ price: "", sow: "", period: "", exclusions: "" });
  const [files, setFiles] = useState<Record<string, File | null>>({});
  const [opportunityId, setOpportunityId] = useState("");
  const [clientId, setClientId] = useState("");
  const [projectId, setProjectId] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [showMoreSources, setShowMoreSources] = useState(!initialSource);
  const focused = initialSource ? sources.find((item) => item.key === initialSource) : null;
  const updateField = (key: string, value: string) => setFields((current) => ({ ...current, [key]: value }));
  const friendlyError = (cause: unknown) => {
    const message = cause instanceof Error ? cause.message : "Proposal could not be created. Review the highlighted fields or source upload and try again.";
    if (message.includes("CAPABILITY_DENIED") || message.includes("ACTION_NOT_ALLOWED")) return "New Proposal intake is handled by Business Development.";
    if (message.includes("PROJECT_REFERENCE_MISMATCH")) return "The selected Project Reference does not match the selected Project.";
    if (message.includes("SOURCE_FILE_REQUIRED")) return "Add at least one Proposal source.";
    if (message.includes("SOR_READBACK_VERIFICATION_FAILED") || message.includes("SOR_UNAVAILABLE")) return "The source could not be verified. Review the source and try again.";
    return message.replace(/\[\d+ [^\]]+\]/, "").trim() || "Proposal could not be created. Review the highlighted fields or source upload and try again.";
  };
  const createProposal = async () => {
    setError("");
    const selected = Object.entries(files).filter(([, file]) => file) as [string, File][];
    if (!description.trim()) { setError("Enter a Proposal Description."); return; }
    if (!selected.length) { setError("Add at least one Proposal source."); return; }
    setBusy(true);
    try {
      let nextId = opportunityId;
      for (const [source, file] of selected) {
        const form = new FormData();
        form.append("action", source);
        form.append("file", file);
        form.append("proposal_description", description.trim());
        form.append("price", fields.price);
        form.append("sow", fields.sow);
        form.append("period", fields.period);
        form.append("exclusions", fields.exclusions);
        form.append("create_new_proposal", "true");
        if (clientId) form.append("client_account_id", clientId);
        if (projectId) {
          const project = projects.find((item) => item.id === projectId);
          form.append("project_id", projectId);
          if (project) form.append("project_reference", project.project_number);
        }
        if (nextId) form.append("opportunity_id", nextId);
        form.append("actor", `${persona.toLowerCase()}@amec.synthetic`);
        form.append("actor_role", persona);
        form.append("idempotency_key", `new-proposal:${source}:${file.name}:${file.size}:${file.lastModified}`);
        const result = await api<any>("/api/proposals-main/intake", { method: "POST", body: form });
        nextId = result.opportunity_id || nextId;
        setOpportunityId(nextId || "");
      }
      if (!nextId) throw new Error("Proposal could not be created. No Proposal reference was returned.");
      onComplete({ message: "Proposal created. Source evidence was read-back verified.", proposalId: nextId });
    } catch (cause) {
      setError(friendlyError(cause));
    } finally { setBusy(false); }
  };
  const content = <>
    <p className="proposal-modal-copy">{focused ? `${focused.helper}. This source is preselected; add another source only when it supports the same Proposal.` : "Start a Proposal from tender and client information. A Proposal may begin before the final AMEC Project Reference exists; ProposalOps keeps a controlled provisional Proposal Reference until the Project Reference is available."}</p>
    <section className="proposal-intake-step"><h3>1. Proposal details</h3><label>Proposal Description<input aria-required="true" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Client inquiry or tender description" /></label><div className="proposal-intake-context-grid"><label>Client<select value={clientId} onChange={(event) => setClientId(event.target.value)}><option value="">Client Information source / select later</option>{clients.map((client) => <option key={client.id} value={client.id}>{client.reference} · {client.name}</option>)}</select><small>Use an existing Client when known; do not create a duplicate from each source.</small></label><label>Project context (optional)<select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">No canonical Project yet</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.project_number} · {project.project_name}</option>)}</select><small>A canonical Project Reference is optional at intake.</small></label></div><div className="proposal-field-grid"><label>Price<input value={fields.price} onChange={(event) => updateField("price", event.target.value)} placeholder="Commercial amount" /></label><label>Period<input value={fields.period} onChange={(event) => updateField("period", event.target.value)} placeholder="Proposal validity / delivery period" /></label><label>Initial SOW / Tender Scope<input value={fields.sow} onChange={(event) => updateField("sow", event.target.value)} placeholder="Initial client or tender scope" /></label><label>Exclusions<input value={fields.exclusions} onChange={(event) => updateField("exclusions", event.target.value)} placeholder="Known commercial exclusions" /></label></div></section>
    <section className="proposal-intake-step"><h3>2. Source evidence</h3><p className="proposal-intake-hint">Add one or more supported intake sources. The selected source remains visible and each source is verified after it is stored.</p>{focused ? <div className="source-intake-primary selected-source"><b>Selected source · {focused.label}</b><FilePicker file={files[focused.key]} accept={focused.key === "TENDER_IMAGE" ? "image/*" : undefined} onChange={(file) => setFiles({ ...files, [focused.key]: file })}/><small>{focused.helper}</small></div> : null}{(showMoreSources || !focused) && <div className="source-intake-grid">{sources.filter((source) => !focused || source.key !== focused.key).map((source) => <div key={source.key} className="source-intake-secondary"><b>{source.label}</b><FilePicker file={files[source.key]} accept={source.key === "TENDER_IMAGE" ? "image/*" : undefined} onChange={(file) => setFiles({ ...files, [source.key]: file })}/><small>{source.helper}</small></div>)}</div>}{focused && !showMoreSources && <button className="text-button" onClick={() => setShowMoreSources(true)}>＋ Add another source</button>}</section>
    {opportunityId && <div className="proposal-destination"><b>Proposal Reference</b><span>{opportunityId}</span><small>Source lineage retained · read-back verified</small></div>}
    {error && <div className="proposal-form-error" role="alert">{error}</div>}
    <div className="proposal-modal-actions"><button className="button-secondary" onClick={onClose}>{fullPage ? "Back to Proposals & Contracts" : "Close"}</button><button className="button-primary proposal-orange-submit" onClick={createProposal} disabled={busy}>{busy ? "Creating Proposal…" : "Create Proposal & Save Sources"}</button></div>
  </>;
  return content;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="proposal-modal-backdrop" role="presentation"><section className="proposal-upload-modal" role="dialog" aria-modal="true" aria-labelledby="manual-upload-title"><div className="panel-head"><div><span className="eyebrow">HUMAN INPUT / UPLOAD</span><h3 id="manual-upload-title">{title}</h3></div><button className="text-button" onClick={onClose}>Close</button></div>{children}</section></div>; }

function FilePicker({ file, accept, onChange }: { file: File | null | undefined; accept?: string; onChange: (file: File | null) => void }) { return <div className="file-picker"><input className="file-picker-input" aria-label="Source file upload" type="file" accept={accept} onChange={(event) => onChange(event.target.files?.[0] || null)} /><button type="button" className="button-secondary file-picker-button" onClick={(event) => { const input = event.currentTarget.previousElementSibling as HTMLInputElement | null; input?.click(); }}>{file ? "Replace file" : "Select file"}</button>{file && <><span className="file-picker-name">{file.name}</span><button type="button" className="text-button" onClick={() => onChange(null)}>Remove</button></>}</div>; }

function ManualUploadModal({ action, projects, proposals, contracts, persona, onClose, onComplete }: { action: typeof actions[number]; projects: Project[]; proposals: any[]; contracts: any[]; persona: Persona; onClose: () => void; onComplete: (result: any) => void }) {
  const [contextId, setContextId] = useState(""); const [file, setFile] = useState<File | null>(null); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const selectedProposal = proposals.find((item) => item.id === contextId); const selectedContract = contracts.find((item) => item.id === contextId); const project = projects.find((item) => item.id === contextId) || projects.find((item) => item.id === selectedProposal?.project_id) || projects.find((item) => item.id === selectedContract?.project_id);
  const copy = action.key === "CLIENT_LIST" ? "Import a controlled client source to reconcile the Client master. This does not create a Proposal." : action.key === "PROPOSAL_FORM" ? "Select the existing eligible Proposal this form belongs to. ProposalOps stores it against the same Proposal and Project lineage." : "Select the existing eligible Contract this form belongs to. ProposalOps stores it against the related Proposal and Project lineage.";
  const title = action.key === "CLIENT_LIST" ? "Client List" : action.label; const contextLabel = action.key === "CLIENT_LIST" ? "Client master context" : action.key === "PROPOSAL_FORM" ? "Eligible Proposal" : "Eligible Contract";
  const submit = async () => { setError(""); if (!contextId) { setError(`Select an existing ${contextLabel.toLowerCase()} before upload.`); return; } if (!file) { setError("Select the source file before upload."); return; } setBusy(true); const form = new FormData(); form.append("action", action.key); form.append("file", file); form.append("actor", `${persona.toLowerCase()}@amec.synthetic`); form.append("actor_role", persona); if (action.key === "CLIENT_LIST") { form.append("project_id", contextId); const target = projects.find((item) => item.id === contextId); form.append("project_reference", target?.project_number || ""); } else if (action.key === "PROPOSAL_FORM") { form.append("opportunity_id", selectedProposal.id); form.append("project_id", selectedProposal.project_id); form.append("project_reference", selectedProposal.project_reference); } else { form.append("contract_id", selectedContract.id); form.append("opportunity_id", selectedContract.related_proposal_id); form.append("project_id", selectedContract.project_id); form.append("project_reference", selectedContract.project_reference); } try { const result = await api<any>("/api/proposals-main/intake", { method: "POST", body: form }); onComplete(result); } catch (e) { setError(e instanceof Error ? e.message : "Upload failed. Retry required."); } finally { setBusy(false); } };
  return <Modal title={title} onClose={onClose}><p className="proposal-modal-copy">{copy}</p><label>{contextLabel}<select value={contextId} onChange={(e) => setContextId(e.target.value)}><option value="">Select {contextLabel.toLowerCase()}…</option>{action.key === "CLIENT_LIST" ? projects.map((item) => <option key={item.id} value={item.id}>{item.project_number} · {item.project_name}</option>) : action.key === "PROPOSAL_FORM" ? proposals.map((item) => <option key={item.id} value={item.id}>{item.proposal_id || item.id} · {item.proposal_description} · {item.project_reference}</option>) : contracts.map((item) => <option key={item.id} value={item.id}>{item.contract_reference} · {item.related_proposal} · {item.project_reference}</option>)}</select>{contextId && action.key !== "CLIENT_LIST" && <small className="context-readback">{project?.project_number || "Project context linked"} · existing lineage selected</small>}</label><label>Source file<FilePicker file={file} onChange={setFile}/><small>Manual file selection is required. Stored bytes are verified by read-back before success.</small></label>{error && <div className="proposal-form-error">{error}</div>}<div className="proposal-modal-actions"><button className="button-secondary" onClick={onClose}>Cancel</button><button className="button-primary" onClick={submit} disabled={busy}>{busy ? "Saving source…" : action.key === "CLIENT_LIST" ? "Save Client Source" : action.key === "PROPOSAL_FORM" ? "Upload Proposal Form" : "Upload Contract Form"}</button></div></Modal>;
}
